/bin/bash -lc "python3 /workspace/tools.py resolve run://r-001 > /workspace/runtime_view.json
python3 - <<'PY'
import json
r=json.load(open('/workspace/runtime_view.json'))
print('TOP KEYS',list(r))
for k,v in r.items():
 if k"'!='"'context': print(k, json.dumps(v,ensure_ascii=False)[:16000])
c=r.get('context',{})
print('CONTEXT KEYS',list(c))
for k,v in c.items():
 if k not in ['history','knowledge']: print(k,json.dumps(v,ensure_ascii=False)[:18000])
print('HISTORY SUMMARY')
for t in c.get('history',[]):
 print(t['id'], t.get('status'), t.get('validation',{}).get('auc'),t.get('wall_seconds'),t.get('note'))
PY"

